using MediatR; using Microsoft.AspNetCore.Http; using Microsoft.AspNetCore.Routing; namespace JTradeERP.Application.Features.MasterData.Categories.DeleteCategory; public static class DeleteCategoryEndpoint { public static void Map(IEndpointRouteBuilder e)=>e.MapDelete("/categories/{id:guid}",async(Guid id,ISender s,CancellationToken ct)=>{await s.Send(new DeleteCategoryCommand(id),ct);return Results.NoContent();}); }
